window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[113]={"id":"113","numero":113,"titre":"Hémangiomes et Malformations vasculaires","objectifs":[{"id":"113-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'un hémangiome et son histoire naturelle","contenu":"<div class=\"callout callout-info\">\n        <strong>Cadre nosologique.</strong> Sous le terme « angiome » ou « anomalie vasculaire », on distingue\n        <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>randes familles</strong> : les <span class=\"kw-def\">tumeurs vasculaires</span> (prolifération endothéliale,\n        dont les hémangiomes infantiles) et les <span class=\"kw-def\">malformations vasculaires</span> (perturbation de la\n        morphogenèse embryonnaire, cellules endothéliales <em>quiescentes</em>).\n      </div>\n\n      <table >\n        <thead><tr><th>Famille</th><th>Bénignes / sous-types</th><th>Malignes</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Tumeurs vasculaires</strong></td>\n            <td>Hémangio-endothéliome (malignité diminuée) · <strong>Hémangiomes</strong> (principalement <span class=\"kw-def\">hémangiomes infantiles / immatures</span>) · Hémangiomes congénitaux</td>\n            <td>Angiosarcomes</td>\n            <td><span class=\"kw-clinique\">Prolifération de cellules endothéliales</span>, touchant le plus souvent les <strong>capillaires</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Malformations vasculaires</strong></td>\n            <td>Simples : capillaires · veineuses · lymphatiques · artério-veineuses<br>Complexes : lymphatico-veineuses · syndromiques</td>\n            <td>—</td>\n            <td>Perturbation de la morphogenèse au cours du développement embryonnaire ; <strong>cellules endothéliales quiescentes</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Hémangiome <em><span class=\"kw-bio\">vs</span></em> malformation vasculaire — distinction sémiologique clé</h4>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Hémangiome</th><th>Malformation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Endothélium</strong></td><td>Proliférant</td><td>Quiescent</td></tr>\n          <tr><td><strong>À la naissance</strong></td><td><span class=\"kw-clinique\">Absent</span></td><td><span class=\"kw-clinique\">Présent</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Évolution</span></strong></td><td><strong>Croissance puis régression</strong>, disparition</td><td><strong>Stabilité ou aggravation</strong>, persistance</td></tr>\n          <tr><td><strong>Principaux types</strong></td><td>Hémangiome infantile</td><td>Capillaire, veineuse, lymphatique, artério-veineuse, mixte</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Histoire naturelle stéréotypée de l'hémangiome infantile (élément diagnostique majeur)</h4>\n      <ul>\n        <li><strong>Avant la phase de croissance</strong> :\n          <ul>\n            <li>Hémangiomes <span class=\"kw-clinique\">absents à la naissance</span> (non congénitaux <strong>❌</strong>)</li>\n            <li>Parfois précédés d'une zone de <strong>vasoconstriction</strong> (<span class=\"kw-clinique\">macule</span> pâle) ou de <strong>vasodilatation</strong> (simulant un angiome plan)</li>\n          </ul>\n        </li>\n        <li><strong>Phase de croissance</strong> :\n          <ul>\n            <li>Début dans les premiers jours/semaines/mois de vie (nouveau-né<span class=\"kw-chiffre\"> 20 %</span>), toujours <strong>avant <span class=\"kw-chiffre\">1 an</span></strong></li>\n            <li>Augmentation rapide pendant les <strong>5–6 premiers mois</strong> (jusqu'à<span class=\"kw-chiffre\"> 1 an</span>)</li>\n          </ul>\n        </li>\n        <li><strong>Phase d'involution spontanée</strong> :\n          <ul>\n            <li>Durée variable : <strong><span class=\"kw-chiffre\">2 à 10 ans</span></strong></li>\n            <li>Blanchiment en surface + diminution progressive de taille</li>\n            <li><span class=\"kw-def\">Disparition complète sans séquelle dans 50 %</span> des cas</li>\n            <li>Séquelles bénignes (télangiectasies, <span class=\"kw-clinique\">nodule</span> fibro-adipeux) dans <span class=\"kw-chiffre\">50 %</span> — PEC esthétique possible</li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-def\">Épidémiologie</span> de l'hémangiome infantile.</strong> Tumeur la plus fréquente de l'enfant — <span class=\"kw-def\">prévalence</span> <strong><span class=\"kw-chiffre\">10 %</span></strong> ·\n        sex-ratio <strong>3 F / <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> G</span></strong> · plus fréquent chez le <strong>prématuré</strong> et le nouveau-né de faible poids.\n      </div>","frequence":4},{"id":"113-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d'un hémangiome","contenu":"<h4>Sémiologie commune des hémangiomes infantiles</h4>\n      <ul>\n        <li>Tuméfactions de taille, siège et nombre variables : <strong>uniques</strong> le plus souvent (forme multiple non rare)</li>\n        <li><span class=\"kw-clinique\">Augmentation de la chaleur locale</span> ⭐</li>\n        <li><strong>Non soufflantes</strong> à l'auscultation</li>\n        <li><strong>Sans battement, ni frémissement</strong> à la palpation</li>\n        <li>Consistance <strong>élastique, rénitente, ferme mais non indurée</strong></li>\n      </ul>\n\n      <h4>3 formes cliniques selon la profondeur</h4>\n      <table >\n        <thead><tr><th>Forme</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hémangiome superficiel</strong><br><em>(angiome tubéreux / cutané pur)</em></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Nodule</span> ou <span class=\"kw-clinique\">plaque</span> <span class=\"kw-clinique\">rouge vif</span>, en <strong>relief</strong></li>\n                <li>Surface <strong>tendue ou mamelonnée</strong></li>\n                <li>Dépressible, devient pâle à la pression mais <strong>sans vidange ni disparition complète ❌</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hémangiome profond</strong><br><em>(sous-cutané / dermique)</em></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Tuméfaction</span> <span class=\"kw-clinique\">bleutée</span>, ou couleur de la peau normale</li>\n                <li><strong>Télangiectasies arborescentes</strong> parfois en surface</li>\n                <li>Consistance plus élastique que les formes superficielles</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hémangiome mixte</strong></td>\n            <td>Associe formes superficielle + profonde — selon le CMF, les formes mixtes sont les <strong>plus fréquentes</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Paraclinique — quand l'<span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">doppler</span></span> ?</h4>\n      <div class=\"callout callout-info\">\n        Le diagnostic est <strong>clinique</strong>. Une <span class=\"kw-ttt\">échographie-doppler</span> est utile si présentation\n        atypique (notamment formes dermiques pures). <em><span class=\"kw-bio\">Biopsie</span> généralement inutile</em>.\n        <ul>\n          <li><span class=\"kw-clinique\">Masse</span> d'<strong>échogénicité variable</strong></li>\n          <li>Richement <strong>vascularisée</strong></li>\n          <li><span class=\"kw-def\">Flux rapide</span> (vitesse systolique élevée) avec index de résistance bas — <strong>signature clé</strong> qui différencie hémangiome (flux rapide) et malformation veineuse/lymphatique (flux lent)</li>\n        </ul>\n      </div>","frequence":4},{"id":"113-3","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les localisations à risque et les complications des hémangiomes","contenu":"<div class=\"callout callout-danger\">\n        <strong>⚠️ Complications</strong> ne concernent qu'une <strong>minorité (<span class=\"kw-chiffre\">10 %</span>)</strong> des hémangiomes, mais\n        peuvent mettre en jeu le <span class=\"kw-alerte\">pronostic esthétique, fonctionnel, voire vital</span>.\n        Certaines localisations imposent un <strong>traitement précoce</strong> et une prise en charge multidisciplinaire.\n      </div>\n\n      <h4>Formes compliquées</h4>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques · conséquences</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Hémangiome ulcéré</strong></td>\n            <td>\n              Tout hémangiome peut s'ulcérer ; localisations à risque : <strong>siège (fesse, vulve), lèvres, plis (cou)</strong>.\n              <ul>\n                <li><span class=\"kw-clinique\">Douleurs</span>, majorées par les <strong>mictions</strong> si atteinte du siège</li>\n                <li><strong>Difficultés d'alimentation</strong> (biberon) si localisation labiale</li>\n                <li><span class=\"kw-alerte\">Surinfection, saignements</span></li>\n                <li>Cicatrice atrophique inesthétique ± défect séquellaire (<span class=\"kw-ttt\">chirurgie</span> réparatrice ultérieure)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hémangiomatose miliaire</strong> <em>(rare)</em></td>\n            <td>\n              <ul>\n                <li>Petits hémangiomes de quelques millimètres à<span class=\"kw-chiffre\"> 1 cm</span>, ± nombreux, sur l'ensemble des téguments</li>\n                <li>Peuvent être associés à des <strong>hémangiomes viscéraux</strong> — essentiellement <span class=\"kw-clinique\">hépatiques ++</span></li>\n                <li><span class=\"kw-alerte\">Insuffisance cardiaque à haut débit</span> si hémangiome hépatique volumineux</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hémangiome géant</strong></td>\n            <td><span class=\"kw-chiffre\">\n              80 %</span> des hémangiomes font &lt;<span class=\"kw-chiffre\"> 2 cm</span>. Les rares formes <em>en plaques</em> peuvent s'accompagner de malformations sous-jacentes à rechercher :\n              <ul>\n                <li><strong>Syndrome PHACES</strong> (visage / extrémité céphalique) : malformations cervelet, cardiaques, gros vaisseaux, oculaires, sternales</li>\n                <li><strong>Syndrome PELVIS / SACRAL</strong> (périnée / lombo-sacrée) : malformations anorectales, génito-urinaires, dysraphie spinale</li>\n              </ul>\n              <em>Justifient une <span class=\"kw-imagerie\">IRM</span>.</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Localisations à risque imposant un traitement précoce</h4>\n      <table >\n        <thead><tr><th>Localisation</th><th>Risques · CAT</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Orbito-palpébral</strong></td>\n            <td>\n              <span class=\"kw-imagerie\">IRM</span> : <span class=\"kw-ttt\">infiltration</span> angiomateuse du cône orbitaire + muscles oculomoteurs.\n              <span class=\"kw-alerte\">Risque d'amblyopie fonctionnelle</span> ⚠️ justifiant un traitement précoce :\n              <ul>\n                <li><strong>Occlusion précoce</strong> de la fente palpébrale</li>\n                <li><strong>Astigmatisme</strong> par compression du globe / déformation cornéenne</li>\n                <li><strong>Déplacement du globe oculaire</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Pointe du nez</strong> <em>(« hémangiome Cyrano »)</em></td>\n            <td>\n              <ul>\n                <li>Préjudice esthétique majeur</li>\n                <li>Déformations séquellaires des cartilages du nez</li>\n                <li><strong><span class=\"kw-ttt\">Chirurgie</span> précoce vers <span class=\"kw-chiffre\">2–3 ans</span></strong> pour repositionner les cartilages alaires</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Sous-glottique</strong></td>\n            <td>\n              Localisation muqueuse profonde — <span class=\"kw-alerte\">obstruction laryngée / trachéale</span> avec <span class=\"kw-alerte\">détresse</span> respiratoire.\n              Peuvent être isolés ou associés à :\n              <ul>\n                <li>Hémangiome muqueux de la lèvre ou de la langue</li>\n                <li>Hémangiome cutané « <strong>en barbe</strong> » : symétrique, mandibulaire, mentonnier, cervical, lèvre inférieure</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Traitement des formes évolutives / à risque.</strong>\n        <ul>\n          <li>Majorité des hémangiomes régresse seule : <strong>pas de traitement ❌</strong></li>\n          <li>Si hémangiome évolutif volumineux, à <span class=\"kw-def\">pronostic</span> fonctionnel/vital ou risque esthétique majeur :\n            <span class=\"kw-ttt\">Propranolol per os en 1ʳᵉ intention</span></li>\n          <li>Séquelles à distance (chez le grand enfant) : cicatrices atrophiques, peau flasque sur tissu fibro-adipeux résiduel → traitement esthétique</li>\n        </ul>\n      </div>","frequence":1},{"id":"113-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels des hémangiomes","contenu":"<table >\n        <thead><tr><th>Entité</th><th>Caractéristiques · piège diagnostique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Tumeurs malignes des parties molles</strong><br><em>(rhabdomyosarcome, fibrosarcome)</em></td>\n            <td>\n              Peuvent avoir une teinte violacée simulant une tumeur vasculaire. Arguments en faveur de la malignité :\n              <ul>\n                <li><strong><span class=\"kw-etio\">Congénitale</span></strong> (présente à la naissance)</li>\n                <li><strong>Unique</strong></li>\n                <li><span class=\"kw-alerte\">Indurée</span> (parfois déformante)</li>\n                <li>Touche le visage ou un segment de membre</li>\n              </ul>\n              → <span class=\"kw-ttt\">Biopsie au moindre doute</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hémangiomes congénitaux</strong></td>\n            <td>\n              Plus rares, parfois dépistés en anténatal, ils ont atteint leur <strong>volume maximal à la naissance</strong>.\n              <ul>\n                <li><strong>RICH</strong> (<em>Rapidly Involuting</em>) : involution rapide en &lt;<span class=\"kw-chiffre\"> 1 an</span></li>\n                <li><strong>NICH</strong> (<em>Non-Involuting</em>) : pas d'involution → <span class=\"kw-ttt\">exérèse chirurgicale</span></li>\n                <li><span class=\"kw-bio\">Histologie</span> : <strong>GLUT-1 négatif</strong>, à l'opposé des hémangiomes infantiles classiques</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Syndrome de Kasabach</span>-Merritt</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Phénomène de coagulation intravasculaire tumorale</span> compliquant certaines tumeurs vasculaires rares.\n              <ul>\n                <li><strong>QCM classique</strong> : l'hémangiome <strong>n'est pas</strong> à l'origine d'un Kasabach-Merritt ⚠️</li>\n                <li>Tumeur vasculaire volumineuse, ecchymotique, violacée, <span class=\"kw-etio\">inflammatoire</span></li>\n                <li><span class=\"kw-alerte\">Thrombopénie majeure</span> → risque <span class=\"kw-etio\">hémorragique</span> mettant en jeu le <span class=\"kw-alerte\">pronostic vital</span> 🔥</li>\n                <li>Prise en charge hospitalière spécialisée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Malformations vasculaires</strong></td>\n            <td>\n              Pièges classiques :\n              <ul>\n                <li>Hémangiome superficiel au <span class=\"kw-def\">stade</span> initial (zone de vasodilatation) peut simuler un <strong>angiome plan</strong></li>\n                <li>Malformations veineuses ou lymphatiques parfois confondues avec hémangiomes profonds</li>\n              </ul>\n              <strong>Examen-clé : <span class=\"kw-ttt\">écho-doppler</span></strong> en 1ʳᵉ intention :\n              <ul>\n                <li>Hémangiome en extension : <span class=\"kw-def\">flux rapide</span></li>\n                <li>Malformation veineuse / lymphatique : <strong>pas de flux rapide</strong> (flux lent)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"113-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d'un angiome plan","contenu":"<div class=\"callout callout-info\">\n        <strong>Définition.</strong> Les angiomes plans (« <em>taches lie de vin</em> ») sont des <span class=\"kw-def\">malformations capillaires</span> :\n        dilatations des capillaires superficiels du derme, présentes <strong>dès la naissance</strong>, sans tendance spontanée à la régression.\n      </div>\n\n      <h4>Caractéristiques cliniques communes</h4>\n      <ul>\n        <li>Taches rouges <strong>planes</strong> (sans relief), couleur lie de vin</li>\n        <li><span class=\"kw-clinique\">Congénitales</span> — à la différence des hémangiomes infantiles</li>\n        <li><strong>Sans souffle, ni frémissement, ni battement</strong> (comme les hémangiomes infantiles)</li>\n        <li><strong>Même température</strong> que la peau normale — à la différence des hémangiomes infantiles (chauds)</li>\n        <li>Disparition à la pression : variable selon les écoles (dermato : ± complète · CMF : non)</li>\n        <li>Topographie : tout territoire cutané, prédilection pour le visage (parfois somatotopie trigéminale)</li>\n      </ul>\n\n      <h4><span class=\"kw-clinique\">Évolution</span> naturelle (sans traitement)</h4>\n      <ul>\n        <li><strong>Persistance</strong> sans tendance à la disparition spontanée ❌</li>\n        <li>Surface augmente <strong>proportionnellement</strong> à la taille de l'enfant</li>\n        <li>Avec le temps : épaississement, peau granuleuse, violacée, nodules rougeâtres</li>\n        <li>Possible <strong>hypertrophie des parties molles</strong> (visage, segment de membre)</li>\n      </ul>\n\n      <h4>Diagnostics différentiels</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Distinction</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Taches angiomateuses physiologiques</strong> <em>(très fréquentes chez le nouveau-né)</em></td>\n            <td>\n              <ul>\n                <li>Couleur plus <strong>pâle (rose saumon)</strong> <span class=\"kw-bio\">vs</span> lie de vin de l'angiome plan</li>\n                <li>Localisations : glabelle (<em><span class=\"kw-clinique\">naevus</span> flammeus</em>), front, paupières, nez, occiput</li>\n                <li><span class=\"kw-def\">Atténuation spontanée en quelques mois</span> ; peuvent persister sur nuque/occiput à l'âge adulte</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hémangiome infantile au <span class=\"kw-def\">stade</span> précoce</strong></td>\n            <td>Zone de vasodilatation initiale précédant l'hémangiome — distinction par l'<span class=\"kw-clinique\">évolution</span> et l'<span class=\"kw-ttt\">écho-doppler</span> (flux rapide pour l'hémangiome)</td>\n          </tr>\n          <tr>\n            <td><strong>Malformations lymphatiques / artério-veineuses</strong> en phase quiescente</td>\n            <td><span class=\"kw-clinique\">Évolution</span> + paraclinique (<span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">doppler</span></span>, <span class=\"kw-imagerie\">IRM</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>⚠️ Formes syndromiques — angiome plan rarement isolé</strong>\n        <ul>\n          <li><strong>Sturge-Weber-Krabbe</strong> (angiomatose encéphalo-trigéminée) : angiome plan <span class=\"kw-chiffre\">≥ 1</span> territoire de <strong>V1</strong> →\n            <span class=\"kw-ttt\">IRM cérébrale</span> à la recherche d'un angiome méningé pie-mère (<span class=\"kw-def\">épilepsie</span> grave, retard psychomoteur) et d'un glaucome <span class=\"kw-etio\">congénital</span></li>\n          <li><strong>Klippel-Trenaunay</strong> (membre inférieur ++) : angiome plan + varices (dysplasie veineuse) +\n            hypertrophie des os/parties molles → <span class=\"kw-alerte\">asymétrie de longueur des membres</span></li>\n          <li><strong>Cobb</strong> : angiome métamérique du tronc + angiome médullaire intra-rachidien (complications nerveuses)</li>\n        </ul>\n      </div>\n\n      <h4>Traitement</h4>\n      <ul>\n        <li>Si retentissement esthétique : <span class=\"kw-ttt\">laser à colorant pulsé</span> → pâlissement</li>\n        <li><span class=\"kw-ttt\">Chirurgie</span> possible selon le CMF</li>\n      </ul>","frequence":0},{"id":"113-6","rang":"B","rubrique":"Suivi et/ou Pronostic","titre":"Connaître les complications d'une malformation veineuse","contenu":"<div class=\"callout callout-info\">\n        <strong>Rappel sémiologique.</strong> Tuméfactions bleutées sous-cutanées ou lacis veineux sous-muqueux dilatés (varices),\n        <strong>molles, dépressibles</strong>, indolores (en dehors des thromboses), <em>sans</em> chaleur locale, battement ni souffle.\n        Sensibilité à la <strong>gravité</strong> ⭐ : se vident à la pression / surélévation, gonflent en position déclive, à l'effort ou aux cris.\n        Paraclinique : <span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">doppler</span></span> (<span class=\"kw-def\">absence de flux spontané</span>, lacs veineux) + <span class=\"kw-imagerie\">IRM</span> (hyperT2) pour l'extension.\n      </div>\n\n      <h4><span class=\"kw-clinique\">Évolution</span> générale</h4>\n      <p><span class=\"kw-clinique\">Aggravation lente au cours de la vie</span>, par poussées (puberté, <span class=\"kw-ci\">grossesse</span>, traumatisme, infection).</p>\n\n      <h4>Complications évolutives</h4>\n      <table >\n        <thead><tr><th>Complication</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Épisodes aigus de thrombose intralésionnelle</strong> <em>(fréquents)</em></td>\n            <td>\n              <ul>\n                <li>Phase 1 : <span class=\"kw-clinique\">nodules douloureux et inflammatoires</span>, régressifs en quelques jours</li>\n                <li>Phase 2 : <span class=\"kw-clinique\">évolution</span> vers <strong>calcification</strong> → <span class=\"kw-clinique\">phlébolithes</span> palpables et visibles en <span class=\"kw-imagerie\">radiographie</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Coagulation intravasculaire localisée</strong> <em>(rare)</em></td>\n            <td>\n              <ul>\n                <li>Possible dans les formes très volumineuses</li>\n                <li>À <strong>dépister avant toute <span class=\"kw-ttt\">chirurgie</span></strong> par dosage : <span class=\"kw-ttt\">plaquettes, fibrinogène, D-Dimères</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Complications spécifiques selon la topographie</h4>\n      <table >\n        <thead><tr><th>Localisation</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Lèvres</strong></td><td><span class=\"kw-clinique\">Incompétence labiale</span> (retentissement esthétique + fonctionnel)</td></tr>\n          <tr><td><strong>Langue</strong></td><td><strong>Macroglossie</strong> → troubles de la phonation et de la croissance mandibulaire</td></tr>\n          <tr><td><strong>Étage orbitaire</strong></td><td>Atteinte conjonctive/sclère possible ; <strong>exophtalmie</strong> sans compression oculaire</td></tr>\n          <tr><td><strong>Temporo-massétérine</strong></td><td>Fréquente (plexus veineux extracrâniens)</td></tr>\n          <tr><td><strong>Membres (loges musculaires)</strong></td><td><span class=\"kw-alerte\">Extension profonde possible</span> ⚠️</td></tr>\n          <tr><td><strong>von Recklinghausen</strong></td><td>Parfois retrouvées au sein des déformations tumorales</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Traitement.</strong> Non univoque, parfois décevant : sclérothérapie, <span class=\"kw-ttt\">laser</span> Diode, <span class=\"kw-ttt\">exérèse chirurgicale</span>, anti-angiogénique.\n        Prise en charge <strong>multidisciplinaire</strong> spécialisée (dermato, radio interventionnelle, angio, <span class=\"kw-ttt\">chirurgie</span>).\n      </div>","frequence":0},{"id":"113-7","rang":"B","rubrique":"Suivi et/ou Pronostic","titre":"Connaître les complications d'une malformation artério-veineuse","contenu":"<div class=\"callout callout-danger\">\n        <strong>⚠️ Malformations artério-veineuses (MAV)</strong> = malformations à <span class=\"kw-alerte\">flux rapide</span>,\n        rares mais de <strong><span class=\"kw-def\">pronostic</span> grave</strong>. Anciens « anévrysmes cirsoïdes ». Présentes dès l'enfance, peuvent rester\n        quiescentes pendant des années puis se révéler sur facteurs déclenchants : <strong>puberté, <span class=\"kw-ci\">grossesse</span>, infection, traumatisme, geste thérapeutique</strong>.\n      </div>\n\n      <h4><span class=\"kw-clinique\">Évolution</span> sémiologique en 3 phases</h4>\n      <ol>\n        <li><strong>Initial</strong> : simple <span class=\"kw-clinique\">tache rouge plane</span>, simule un angiome plan, mais <strong>plus chaude</strong></li>\n        <li><strong>Extension</strong> : devient <strong>battante</strong> (battement pulsatile), <strong>frémissement (thrill)</strong> à la palpation, <strong>souffle</strong> à l'auscultation</li>\n        <li><strong>Tardif</strong> : <span class=\"kw-clinique\">tuméfaction</span> / déformation localisée</li>\n      </ol>\n\n      <p><em><span class=\"kw-def\">Classification</span> de Schobinger (rang C, CMF)</em> : I quiescence · II expansion · III destruction (<span class=\"kw-clinique\">nécrose</span>, infection, hémorragie, douleurs) · IV <span class=\"kw-alerte\">décompensation cardiaque</span>.</p>\n\n      <h4>Localisations préférentielles</h4>\n      <p>Face, oreilles, cuir chevelu, extrémités des membres.</p>\n\n      <h4>Paraclinique</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Écho-doppler</span> : <span class=\"kw-def\">flux rapide</span> (courbes vélocimétriques artérielles comparables à l'hémangiome)</li>\n        <li><strong><span class=\"kw-imagerie\">IRM</span></strong> (préférée à la <span class=\"kw-imagerie\">TDM</span>) : extension en profondeur</li>\n        <li><strong>Artériographie</strong> (ou <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">IRM</span></span>) : <span class=\"kw-def\">bilan préthérapeutique</span>, visualise le <strong>nidus</strong> et l'élargissement du réseau artériel</li>\n      </ul>\n\n      <h4>Complications ⚠️ (<span class=\"kw-def\">pronostic</span> grave)</h4>\n      <table >\n        <thead><tr><th>Risque</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Hémorragie</span></strong></td>\n            <td>Peut être le <strong>mode de révélation</strong> · cataclysmique possible (notamment MAV maxillo-mandibulaire lors d'une <span class=\"kw-ttt\">extraction dentaire</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Nécrose ischémique cutanée</span></strong></td>\n            <td>Au <span class=\"kw-def\">stade</span> de destruction (Schobinger III)</td>\n          </tr>\n          <tr>\n            <td><strong>Invasion locorégionale</strong></td>\n            <td>Au <strong>visage</strong> : allures défigurantes monstrueuses · syndrome de <em>Bonnet-Dechaume-Blanc</em> (MAV médiofrontale + extension oculaire et encéphalique)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Décompensation</span> cardiaque</strong> <em>(rare,<span class=\"kw-chiffre\"> 2 %</span>)</em></td>\n            <td>Par <span class=\"kw-alerte\">« vol sanguin »</span> au sein du nidus (cœur de la malformation)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Traitement.</strong> Difficile, requérant des compétences combinées (<strong>radiologie interventionnelle + <span class=\"kw-ttt\">chirurgie</span></strong>).\n        <span class=\"kw-alerte\">Caractère récidivant après traitement</span> ; le geste insuffisant ou trop économe peut réactiver le processus\n        et aggraver le tableau jusqu'à des « impasses thérapeutiques ». L'embolisation est indispensable dans les formes\n        évolutives/destructrices, combinée à l'<strong><span class=\"kw-ttt\">exérèse</span> chirurgicale large</strong> quand envisageable.\n      </div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-chiffre\">10%</span> des hémangiomes sont <span class=\"kw-etio\">compliqués</span> et engagent le <span class=\"kw-def\">pronostic</span> <span class=\"kw-alerte\">esthétique, fonctionnel voire vital</span><br><strong>Fenêtre thérapeutique :</strong> croissance rapide les <span class=\"kw-chiffre\">5-6 premiers mois</span> (jusqu'à <span class=\"kw-chiffre\">1 an</span>) → traiter tôt les <span class=\"kw-alerte\">localisations à risque</span> avant les séquelles<br><strong>1er geste :</strong> reconnaître une localisation à risque → <span class=\"kw-ttt\">propranolol per os</span> précoce + avis multidisciplinaire</p>","hospit":"<p><strong>Ambulatoire :</strong> hémangiome typique <span class=\"kw-def\">non compliqué</span> → simple <span class=\"kw-def\">surveillance</span>, aucun traitement<br><strong>PEC spécialisée multidisciplinaire :</strong> formes compliquées, localisations à risque et malformations (dermatologues, radiologues, angiologues, chirurgiens)<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-etio\">syndrome de Kasabach-Merritt</span> (tumeur vasculaire rare) → <span class=\"kw-alerte\">thrombopénie majeure</span>, PEC hospitalière spécialisée</p>","redflags":"<ul><li>Localisation <span class=\"kw-alerte\">orbito-palpébrale</span> → risque d'<span class=\"kw-etio\">amblyopie fonctionnelle</span> (occlusion de la fente palpébrale, astigmatisme)</li><li>Localisation <span class=\"kw-alerte\">sous-glottique</span> ou hémangiome cutané « en barbe » → <span class=\"kw-alerte\">obstruction laryngée/trachéale</span> avec <span class=\"kw-etio\">détresse respiratoire</span></li><li>Hémangiome de la <span class=\"kw-clinique\">pointe du nez</span> (« Cyrano ») → déformation séquellaire des cartilages alaires</li><li>Hémangiome <span class=\"kw-etio\">ulcéré</span> : douleur, <span class=\"kw-etio\">surinfection</span>, saignement</li><li>Hémangiome <span class=\"kw-clinique\">géant</span> → rechercher un <span class=\"kw-etio\">syndrome PHACES</span> (visage/extrémité céphalique) ou <span class=\"kw-etio\">PELVIS/SACRAL</span> (périnée, région lombo-sacrée)</li><li><span class=\"kw-etio\">Hémangiomatose miliaire</span> avec hémangiomes <span class=\"kw-etio\">hépatiques</span> volumineux → <span class=\"kw-alerte\">insuffisance cardiaque à haut débit</span></li><li>MAV : <span class=\"kw-alerte\">hémorragie</span>, <span class=\"kw-etio\">nécrose ischémique</span> cutanée, <span class=\"kw-alerte\">décompensation cardiaque</span> par vol sanguin</li></ul>","principes":"<p>La <span class=\"kw-def\">majorité des hémangiomes régresse spontanément</span> et ne nécessite aucun traitement ; on traite les formes à risque et les malformations selon le type</p><p><strong>Hémangiome non compliqué</strong></p><p><span class=\"kw-def\">Surveillance</span> simple</p><ul><li><span class=\"kw-ttt\">Abstention thérapeutique</span> : régression spontanée</li><li>Involution sur <span class=\"kw-chiffre\">2 à 10 ans</span></li><li>Disparition sans séquelle dans <span class=\"kw-chiffre\">50%</span> des cas</li></ul><p><strong>Hémangiome compliqué / localisation à risque</strong></p><p>Traitement précoce + PEC multidisciplinaire</p><ul><li><span class=\"kw-ttt\">Propranolol per os</span> en <span class=\"kw-chiffre\">1ère intention</span></li><li><span class=\"kw-imagerie\">IRM</span> si hémangiome géant (recherche <span class=\"kw-etio\">PHACES</span> / <span class=\"kw-etio\">PELVIS-SACRAL</span>)</li><li><span class=\"kw-ttt\">Chirurgie</span> précoce vers <span class=\"kw-chiffre\">2-3 ans</span> pour l'hémangiome « Cyrano »</li></ul><p><strong>Malformations vasculaires</strong></p><p>PEC spécialisée multidisciplinaire (sauf malformation capillaire)</p><ul><li>Angiome plan (capillaire) : <span class=\"kw-ttt\">laser à colorant pulsé</span> si retentissement esthétique</li><li>Malformation veineuse : <span class=\"kw-ttt\">sclérothérapie</span>, <span class=\"kw-ttt\">laser</span>, exérèse</li><li>MAV : <span class=\"kw-ttt\">embolisation</span> + <span class=\"kw-ttt\">exérèse chirurgicale</span></li><li>Malformation lymphatique : <span class=\"kw-ttt\">antibiothérapie</span> + <span class=\"kw-ttt\">corticoïdes</span> lors des poussées</li></ul>","suivi":"<p><strong>Hémangiome :</strong> surveiller l'<span class=\"kw-def\">involution spontanée</span> (<span class=\"kw-chiffre\">2 à 10 ans</span>) et dépister les séquelles (<span class=\"kw-etio\">télangiectasies</span>, <span class=\"kw-etio\">nodule fibro-adipeux</span>, <span class=\"kw-chiffre\">50%</span> des cas)<br><strong>Malformation veineuse :</strong> avant toute <span class=\"kw-ttt\">chirurgie</span>, dépister une coagulation intravasculaire localisée par <span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">fibrinogène</span>, <span class=\"kw-bio\">D-Dimères</span><br><strong>Malformations :</strong> pas de régression, <span class=\"kw-clinique\">évolution</span> par poussées → <span class=\"kw-def\">suivi</span> spécialisé prolongé</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/hereditary-haemorrhagic-telangiectasia","label":"Radiopaedia : Hereditary haemorrhagic telangiectasia (Rendu-Osler)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"<span class=\"kw-clinique\">Lésion</span> vasculaire cutanée du nourrisson / enfant — Histoire naturelle + <span class=\"kw-imagerie\">écho-doppler</span> si doute","detail":"<h4>CAT — Anomalie vasculaire cutanée de l'enfant — Hémangiome infantile <span class=\"kw-bio\">vs</span> malformation vasculaire : diagnostic et conduite à tenir</h4>","branches":[{"to":"q-hemangiome","label":"Absente à la naissance, croissance puis régression","color":"blue"},{"to":"q-malf","label":"Présente dès la naissance, stable ou aggravation","color":"blue"}]},{"id":"q-hemangiome","kind":"decision","label":"Hémangiome infantile : forme compliquée ou localisation à risque ? — Absent à la naissance, croissance puis régression ; <span class=\"kw-radio\">flux rapide</span>, index de résistance bas","branches":[{"to":"t-abstention","label":"Typique, non compliqué","color":"green"},{"to":"t-propranolol","label":"Évolutif volumineux / localisation à risque","color":"red"},{"to":"t-biopsie","label":"Atypique : congénital, unique, induré","color":"amber"}]},{"id":"t-abstention","kind":"terminal","label":"Abstention + surveillance de l'involution","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Aucun traitement</span> : régression spontanée de la majorité</li><li>Involution sur <span class=\"kw-chiffre\">2 à 10 ans</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Dépister les séquelles : <span class=\"kw-etio\">télangiectasies</span>, <span class=\"kw-etio\">nodule fibro-adipeux</span> (<span class=\"kw-chiffre\">50%</span>)</li><li>Traitement <span class=\"kw-ttt\">esthétique</span> à distance chez le grand enfant si séquelle</li></ul>"},{"id":"t-propranolol","kind":"terminal","label":"Propranolol per os + PEC multidisciplinaire — Traitement précoce des localisations à risque","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Orbito-palpébral</span> → <span class=\"kw-etio\">amblyopie</span></li><li><span class=\"kw-alerte\">Sous-glottique</span> / « en barbe » → <span class=\"kw-etio\">détresse respiratoire</span></li><li>Pointe du nez (« Cyrano »), hémangiome <span class=\"kw-etio\">ulcéré</span> ou volumineux évolutif</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM</span> si hémangiome géant : <span class=\"kw-etio\">PHACES</span> (face/céphalique), <span class=\"kw-etio\">PELVIS/SACRAL</span> (périnée, lombo-sacré)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Propranolol per os</span> en <span class=\"kw-chiffre\">1ère intention</span></li><li><span class=\"kw-ttt\">Chirurgie</span> précoce vers <span class=\"kw-chiffre\">2-3 ans</span> pour le « Cyrano »</li></ul>"},{"id":"t-biopsie","kind":"terminal","label":"Biopsie au moindre doute — Éliminer une tumeur maligne","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-clinique\">congénitale</span>, <span class=\"kw-clinique\">unique</span>, <span class=\"kw-clinique\">indurée</span> → évoque <span class=\"kw-etio\">rhabdomyosarcome</span> / <span class=\"kw-etio\">fibrosarcome</span></li><li><span class=\"kw-etio\">Hémangiome congénital</span> RICH (involution rapide) ou NICH (sans involution), <span class=\"kw-bio\">GLUT-1 négatif</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Biopsie</span> au moindre doute</li><li>NICH → <span class=\"kw-ttt\">exérèse chirurgicale</span></li></ul>"},{"id":"q-malf","kind":"decision","label":"Malformation vasculaire : écho-doppler — flux rapide ou flux lent ? — Présente dès la naissance, sans régression spontanée","branches":[{"to":"t-mav","label":"Flux rapide","color":"red"},{"to":"t-flux-lent","label":"Flux lent","color":"amber"}]},{"id":"t-mav","kind":"terminal","label":"MAV — PEC spécialisée (pronostic grave) — Flux rapide, pronostic grave","color":"red","detail":"<h4>Clinique</h4><ul><li>Tache rouge chaude → <span class=\"kw-clinique\">battante</span>, <span class=\"kw-clinique\">thrill</span>, <span class=\"kw-clinique\">souffle</span></li><li>Risque : <span class=\"kw-alerte\">hémorragie</span>, <span class=\"kw-etio\">nécrose ischémique</span>, <span class=\"kw-alerte\">décompensation cardiaque</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM</span> / <span class=\"kw-imagerie\">angio-IRM</span> + <span class=\"kw-imagerie\">artériographie</span> (<span class=\"kw-def\">bilan préthérapeutique</span>, nidus)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Embolisation</span> + <span class=\"kw-ttt\">exérèse chirurgicale</span></li><li>Équipe multidisciplinaire ; caractère <span class=\"kw-etio\">récidivant</span></li></ul>"},{"id":"t-flux-lent","kind":"terminal","label":"Malformation à flux lent — PEC selon le type — Capillaire, veineuse ou lymphatique","color":"amber","detail":"<h4>Conduite</h4><ul><li>Capillaire (angiome plan) : <span class=\"kw-ttt\">laser à colorant pulsé</span> si retentissement esthétique</li><li>Veineuse : <span class=\"kw-ttt\">sclérothérapie</span> / <span class=\"kw-ttt\">laser</span> / exérèse ; dépister coagulopathie (<span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">fibrinogène</span>, <span class=\"kw-bio\">D-Dimères</span>)</li><li>Lymphatique : <span class=\"kw-ttt\">antibiothérapie</span> + <span class=\"kw-ttt\">corticoïdes</span> lors des poussées</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Pas de régression spontanée → <span class=\"kw-def\">suivi</span> <span class=\"kw-ttt\">multidisciplinaire</span> prolongé</li></ul>"}]},"cards":[{"i":"5db564bfd6ce","n":113,"o":"113-1","u":"Définition","t":"Connaître la définition d'un hémangiome et son histoire naturelle","q":"Comment se déroule l'histoire naturelle stéréotypée et spontanée de l'hémangiome infantile ?","a":"<p>L'histoire naturelle de l'hémangiome infantile comprend 3 phases :</p><ul><li><strong>Phase pré-croissance</strong> : Généralement <strong>absent à la naissance</strong>, parfois précédé d'une macule pâle ou d'une zone de vasodilatation.</li><li><strong>Phase de croissance</strong> : Débute dans les premiers jours/semaines, avec une <strong>augmentation rapide</strong> pendant les <strong>5 à 6 premiers mois</strong> (toujours avant 1 an).</li><li><strong>Phase d'involution spontanée</strong> : Dure de <strong>2 à 10 ans</strong>, caractérisée par un blanchiment et une diminution de taille. Elle conduit à une disparition complète sans séquelle dans 50 % des cas, mais des séquelles bénignes (télangiectasies, nodule fibro-adipeux) sont possibles dans l'autre moitié des cas.</li></ul>"},{"i":"ae8c2cdf8b71","n":113,"o":"113-1","u":"Définition","t":"Connaître la définition d'un hémangiome et son histoire naturelle","q":"Quelle est la définition d'un hémangiome infantile et son cadre nosologique par rapport aux malformations vasculaires ?","a":"<p>Un hémangiome infantile est une <strong>tumeur vasculaire</strong> résultant d'une <strong>prolifération de cellules endothéliales</strong>. Il se distingue des <strong>malformations vasculaires</strong> qui sont des anomalies du développement embryonnaire avec des cellules endothéliales <strong>quiescentes</strong>.</p>"},{"i":"e03d55610942","n":113,"o":"113-1","u":"Définition","t":"Connaître la définition d'un hémangiome et son histoire naturelle","q":"Quelles sont les principales caractéristiques sémiologiques permettant de distinguer un hémangiome d'une malformation vasculaire ?","a":"<ul><li><strong>Endothélium</strong> : Proliférant dans l'hémangiome vs. quiescent dans la malformation.</li><li><strong>À la naissance</strong> : Absent (ou très discret) pour l'hémangiome vs. présent pour la malformation.</li><li><strong>Évolution</strong> : L'hémangiome croît puis régresse spontanément, tandis que la malformation est stable ou s'aggrave, persistant toute la vie.</li></ul>"},{"i":"0a050d15c996","n":113,"o":"113-2","u":"Diagnostic positif","t":"Connaître les signes cliniques d'un hémangiome","q":"Comment se présentent cliniquement les hémangiomes infantiles, indépendamment de leur profondeur ?","a":"<p>Les hémangiomes infantiles se présentent comme des <strong>tuméfactions</strong> de taille, siège et nombre variables (souvent uniques). Ils se caractérisent par :</p><ul><li>Une <strong>augmentation de la chaleur locale</strong>.</li><li>L'<strong>absence de souffle</strong> à l'auscultation.</li><li>L'<strong>absence de battement ou de frémissement</strong> à la palpation.</li><li>Une <strong>consistance élastique, rénitente</strong>, ferme mais non indurée.</li></ul>"},{"i":"65e448c1870b","n":113,"o":"113-2","u":"Diagnostic positif","t":"Connaître les signes cliniques d'un hémangiome","q":"Quelles sont les particularités cliniques d'un hémangiome profond (sous-cutané) ?","a":"<p>L'hémangiome profond est une <strong>tuméfaction bleutée</strong>, ou de couleur de peau normale. Des <strong>télangiectasies arborescentes</strong> peuvent être visibles en surface. Sa consistance est généralement plus élastique que celle des formes superficielles.</p>"},{"i":"e741b820d269","n":113,"o":"113-2","u":"Diagnostic positif","t":"Connaître les signes cliniques d'un hémangiome","q":"Quelles sont les caractéristiques cliniques spécifiques d'un hémangiome superficiel (ou angiome tubéreux) ?","a":"<p>L'hémangiome superficiel se manifeste comme un <strong>nodule ou une plaque rouge vif</strong>, en relief, avec une surface tendue ou mamelonnée. Il est dépressible et devient <strong>pâle à la pression</strong>, mais sans vidange ni disparition complète.</p>"},{"i":"18a25f668bdd","n":113,"o":"113-3","u":"Identifier une urgence","t":"Connaître les localisations à risque et les complications des hémangiomes","q":"Qu'est-ce qu'une hémangiomatose miliaire et quelles sont ses complications potentielles ?","a":"<p>L'hémangiomatose miliaire est caractérisée par de <strong>petits hémangiomes cutanés</strong> (quelques millimètres à 1 cm), souvent nombreux sur l'ensemble des téguments. Elle peut être associée à des <strong>hémangiomes viscéraux</strong>, principalement hépatiques, qui, s'ils sont volumineux, peuvent induire une <strong>insuffisance cardiaque à haut débit</strong>.</p>"},{"i":"756a3b2be528","n":113,"o":"113-3","u":"Identifier une urgence","t":"Connaître les localisations à risque et les complications des hémangiomes","q":"Quels sont les risques et les conséquences d'un hémangiome orbito-palpébral chez le nourrisson ?","a":"<p>Un hémangiome orbito-palpébral présente un risque d'<strong>amblyopie fonctionnelle</strong>, justifiant un traitement précoce, par :</p><ul><li>Occlusion précoce de la fente palpébrale</li><li>Astigmatisme par compression du globe oculaire et déformation cornéenne</li><li>Déplacement du globe oculaire</li></ul>"},{"i":"7a089dea8de3","n":113,"o":"113-3","u":"Identifier une urgence","t":"Connaître les localisations à risque et les complications des hémangiomes","q":"Quels sont les risques spécifiques d'un hémangiome sous-glottique ?","a":"<p>L'hémangiome sous-glottique est une localisation muqueuse profonde qui présente un risque d'<strong>obstruction laryngée ou trachéale</strong>, pouvant entraîner une <strong>détresse respiratoire</strong>.</p>"},{"i":"9e9c704590a8","n":113,"o":"113-3","u":"Identifier une urgence","t":"Connaître les localisations à risque et les complications des hémangiomes","q":"Quels syndromes malformatifs peuvent être associés à un hémangiome géant localisé à la tête ou au périnée ?","a":"<p>Les hémangiomes géants en plaque, rares, peuvent être associés à :</p><ul><li>Le <strong>Syndrome PHACES</strong> pour les localisations à la tête et l'extrémité céphalique (malformations cérébelleuses, cardiaques, des gros vaisseaux, oculaires, sternales).</li><li>Le <strong>Syndrome PELVIS / SACRAL</strong> pour les localisations périnéales et lombo-sacrées (malformations anorectales, génito-urinaires, dysraphie spinale).</li></ul>"},{"i":"b517767ea26f","n":113,"o":"113-3","u":"Identifier une urgence","t":"Connaître les localisations à risque et les complications des hémangiomes","q":"Quelles sont les localisations des hémangiomes les plus à risque d'ulcération ?","a":"<p>Les hémangiomes peuvent s'ulcérer à n'importe quelle localisation, mais les zones les plus à risque sont :</p><ul><li>Le <strong>siège</strong> (fesses, vulve)</li><li>Les <strong>lèvres</strong></li><li>Les <strong>plis</strong> (notamment le cou)</li></ul>"}]};